package main

import (
	"encoding/json"
	"fmt"
	"log"
	"sync"

	"github.com/jepsen-io/maelstrom/demo/go"
)

// State per node - we use a simple approach: when we receive a rumor, we tell all neighbors
// To ensure eventual consistency even with partitions, we should propagate to more than just direct neighbors
type NodeState struct {
	mu         sync.Mutex
	knownRumors map[int]bool
}

func NewNode(id string) *go.Node {
	node := go.NewNode(id)
	state := &NodeState{
		knownRumors: make(map[int]bool),
	}

	// Handle all message types that might come in
	node.Handle("broadcast", func(ctx *go.Context, msg *go.Message) {
		var tell TellRequest
		if err := json.Unmarshal(msg.Body.RawBody(), &tell); err == nil {
			// We got a "tell" message (client sends broadcast/tell)
			log.Printf("[%s] received tell for rumor %d", id, tell.Rumor)

			state.mu.Lock()
			state.knownRumors[tell.Rumor] = true
			state.mu.Unlock()

			// Propagate to all neighbors we know about
			for _, neighbor := range state.getNeighbors(msg) {
				ctx.RPC(neighbor, tell).Reply("broadcast_ok", nil)
			}

			// Also propagate to ourselves - if we get a tell for something we don't know yet
			log.Printf("[%s] now knowing rumors: %v", id, state.knownRumors)
		} else {
			// Handle other message types (neighbors recall) differently below
		}

		node.Reply("broadcast_ok", nil)
	})

	node.Handle("read", func(ctx *go.Context, msg *go.Message) {
		// Client asking for rumors - just return what we know
		var recalled RecallResponse
		recalled.Rumors = make([]int, 0)

		state.mu.Lock()
		for rumor := range state.knownRumors {
			recalled.Rumors = append(recalled.Rumors, rumor)
		}
		state.mu.Unlock()

		recalled.Messages = recalled.Rumors

		body, _ := json.Marshal(recalled)
		ctx.Write(string(body))
	})

	node.Handle("neighbors", func(ctx *go.Context, msg *go.Message) {
		var topology TopologyRequest
		if err := json.Unmarshal(msg.Body.RawBody(), &topology); err == nil && len(topology.Neighbors) > 0 {
			// Store neighbors for this node
			for neighborID, list := range topology.Neighbors {
				state.mu.Lock()
				state.neighbors[neighborID] = list
				state.mu.Unlock()
			}
			log.Printf("[%s] stored topology: %v", id, state.getNeighbors(nil))
		}

		body, _ := json.Marshal(topologyOk{NeighborsNoted: true})
		ctx.Write(string(body))
	})

	node.Run()
}

func (state *NodeState) getNeighbors(msg *go.Message) []string {
	state.mu.Lock()
	defer state.mu.Unlock()

	if len(state.neighbors) == 0 && msg != nil {
		var topology TopologyRequest
		body := msg.Body.RawBody()
		if err := json.Unmarshal(body, &topology); err == nil && len(topology.Neighbors) > 0 {
			for neighborID, list := range topology.Neighbors {
				state.neighbors[neighborID] = list
			}
		}
	}

	result := make([]string, 0)
	for n := range state.neighbors {
		result = append(result, n)
	}
	return result
}

// Handle neighbors message separately to avoid conflict
func main() {
	node := go.NewNode("n")
	state := &NodeState{knownRumors: make(map[int]bool)}

	// Message handler with context access to all handlers
	type tellRequest struct {
		Mid    int  `json:"msg_id"`
		Rumor  int  `json:"rumor"`
		Type   string `json:"type"`
	}

	type neighborsRequest struct {
		Mid       int                   `json:"msg_id"`
		Neighbors map[string][]string   `json:"neighbors"`
		Type      string                `json:"type"`
	}

	type neighborsResponse struct {
		Type         string `json:"type"`
		InReplyTo    int    `json:"in_reply_to"`
		NeighborsNoted bool  `json:"neighbors_noted,omitempty"`
	}

	type recalled struct {
		Type      string   `json:"type"`
		Mid       int      `json:"msg_id,omitempty"`
		Rumors    []int    `json:"rumors,omitempty"`
		Messages  []int    `json:"messages,omitempty"`
		InReplyTo int      `json:"in_reply_to"`
	}

	type recallResponse struct {
		Type       string   `json:"type"`
		Mid        int      `json:"msg_id"`
		Rumors     []int    `json:"rumors"`
		Messages   []int    `json:"messages,omitempty"`
		InReplyTo  int      `json:"in_reply_to"`
	}

	type topologyRequest struct {
		Type       string                  `json:"type"`
		Neighbors  map[string][]string     `json:"neighbors"`
		Mid        int                     `json:"msg_id"`
		Ok         bool                    `json:"neighbors_noted,omitempty"`
		InReplyTo  int                     `json:"in_reply_to"`
	}

	var neighborsCache map[string]map[string]bool

	node.Handle("broadcast", func(ctx *go.Context, msg *go.Message) {
		body := msg.Body.RawBody()

		type tell struct {
			Mid    int  `json:"msg_id"`
			Rumor  int  `json:"rumor"`
			Type   string `json:"type"`
		}

		var t tell
		if json.Unmarshal(body, &t) != nil {
			// Not a tell message - might be neighbors or recall
			handleOther(ctx, body, msg)
		} else if !t.InReplyTo == 0 || t.Type != "tell" {
			// It's not a tell (could be neighbors response or recall)
			handleOther(ctx, body, msg)
		}

		state.mu.Lock()
		state.knownRumors[t.Rumor] = true
		state.mu.Unlock()

		// Reply to broadcast_ok
		type told struct {
			Type           string `json:"type"`
			InReplyTo      int    `json:"in_reply_to"`
			NeighborsNoted bool   `json:"neighbors_noted,omitempty"`
		}
		toldResp := told{Type: "told", InReplyTo: t.Mid}
		body, _ = json.Marshal(toldResp)
		ctx.Write(string(body))

		// Send to neighbors if we have them
		if len(neighborsCache) > 0 {
			for neighborID := range neighborsCache {
				if msg.Src != neighborID {
					type broadcast struct {
						Type   string `json:"type"`
						Rumor  int    `json:"rumor"`
						Mid    int    `json:"msg_id"`
					}
					bcast := broadcast{Type: "tell", Rumor: t.Rumor, Mid: t.Mid + 1000}
					body, _ = json.Marshal(bcast)
					ctx.Send(neighborID, string(body))
				}
			}
		}
	})

	node.Handle("read", func(ctx *go.Context, msg *go.Message) {
		body := msg.Body.RawBody()

		type recall struct {
			Type      string `json:"type"`
			Mid       int    `json:"msg_id"`
			Rumors    []int  `json:"rumors,omitempty"`
			Messages  []int  `json:"messages,omitempty"`
			InReplyTo int    `json:"in_reply_to"`
		}

		var r recall
		if json.Unmarshal(body, &r) != nil || r.Type != "recall" {
			handleOther(ctx, body, msg)
		} else {
			state.mu.Lock()
			recalledList := make([]int, 0)
			for rumor := range state.knownRumors {
				recalledList = append(recalledList, rumor)
			}
			state.mu.Unlock()

			type recalledMsg struct {
				Type      string   `json:"type"`
				Mid       int      `json:"msg_id"`
				Rumors    []int    `json:"rumors"`
				Messages  []int    `json:"messages,omitempty"`
				InReplyTo int      `json:"in_reply_to"`
			}
			recalledMsgResp := recalledMsg{Type: "recalled", InReplyTo: r.Mid, Messages: recalledList}
			body, _ = json.Marshal(recalledMsgResp)
			ctx.Write(string(body))
		}
	})

	node.Handle("neighbors", func(ctx *go.Context, msg *go.Message) {
		body := msg.Body.RawBody()

		type topology struct {
			Type         string                  `json:"type"`
			Neighbors    map[string][]string     `json:"neighbors"`
			Mid          int                     `json:"msg_id"`
			InReplyTo    int                     `json:"in_reply_to"`
			NeighborsNoted bool                   `json:"neighbors_noted,omitempty"`
		}

		var topo topology
		if json.Unmarshal(body, &topo) != nil {
			handleOther(ctx, body, msg)
		} else {
			// Cache the topology
			for nid, nl := range topo.Neighbors {
				for _, n := range nl {
					if neighborsCache == nil {
						neighborsCache = make(map[string]map[string]bool)
					}
					if neighborsCache[nid] == nil {
						neighborsCache[nid] = make(map[string]bool)
					}
					neighborsCache[nid][n] = true
				}
			}

			type topologyOk struct {
				Type          string `json:"type"`
				InReplyTo     int    `json:"in_reply_to"`
				NeighborsNoted bool   `json:"neighbors_noted"`
			}
			tope := topologyOk{Type: "topology_ok", InReplyTo: topo.Mid, NeighborsNoted: true}
			body, _ = json.Marshal(tope)
			ctx.Write(string(body))
		}
	})

	node.Run()
}

package main

import (
	"encoding/json"
	"log"
	"sync"

	"github.com/jepsen-io/maelstrom/demo/go"
)

type tellRequest struct {
	Mid  int    `json:"msg_id"`
	Rumor int   `json:"rumor"`
	Type string `json:"type"`
}

type neighborsRequest struct {
	Mid       int                   `json:"msg_id"`
	Neighbors map[string][]string   `json:"neighbors"`
	Type      string                `json:"type"`
	InReplyTo int                  `json:"in_reply_to,omitempty"`
}

type tellResponse struct {
	Type           string `json:"type"`
	InReplyTo      int    `json:"in_reply_to"`
	NeighborsNoted bool   `json:"neighbors_noted,omitempty"`
}

type recalled struct {
	Type       string   `json:"type"`
	Mid        int      `json:"msg_id"`
	Rumors     []int    `json:"rumors"`
	Messages   []int    `json:"messages,omitempty"`
	InReplyTo  int      `json:"in_reply_to"`
}

type neighborsNoted struct {
	Type         string `json:"type"`
	InReplyTo    int    `json:"in_reply_to"`
	NeighborsNoted bool  `json:"neighbors_noted,omitempty"`
}

// Node keeps track of known rumors and neighbor list
type nodeState struct {
	mu            sync.RWMutex
	knownRumors   map[int]bool
	neighborList  []string // ordered list of neighbors we should send to
}

func NewNode(id string) *go.Node {
	state := &nodeState{
		knownRumors: make(map[int]bool),
		neighborList: make([]string, 0),
	}

	node := go.NewNode(id)

	// Handle tell messages from clients (broadcast type)
	node.Handle("broadcast", func(ctx *go.Context, msg *go.Message) {
		body := msg.Body.RawBody()

		var tellReq tellRequest
		if err := json.Unmarshal(body, &tellReq); err != nil || tellReq.Type != "tell" {
			handleOther(ctx, body, state, log.Fatal("unhandled broadcast message"))
		}

		state.mu.Lock()
		state.knownRumors[tellReq.Rumor] = true
		state.mu.Unlock()

		// Reply to client with told
		toldResp := tellResponse{Type: "told", InReplyTo: tellReq.Mid}
		respBody, _ := json.Marshal(toldResp)
		ctx.Write(string(respBody))

		// Send to our neighbors (using a unique msg_id for internal propagation)
		for _, neighborID := range state.neighborList {
			if msg.Src != neighborID { // don't send back to sender
				propMessage := tellRequest{Type: "tell", Rumor: tellReq.Rumor, Mid: tellReq.Mid + 1}
				body, _ := json.Marshal(propMessage)
				ctx.Send(neighborID, string(body))
			}
		}
	})

	node.Handle("read", func(ctx *go.Context, msg *go.Message) {
		body := msg.Body.RawBody()

		var recallReq struct {
			Type      string `json:"type"`
			Mid       int    `json:"msg_id"`
			Rumors    []int  `json:"rumors,omitempty"`
			Messages  []int  `json:"messages,omitempty"`
			InReplyTo int    `json:"in_reply_to"`
		}

		if err := json.Unmarshal(body, &recallReq); err != nil || recallReq.Type != "recall" {
			handleOther(ctx, body, state, log.Fatal("unhandled read message"))
		}

		state.mu.RLock()
		recalledList := make([]int, 0)
		for rumor := range state.knownRumors {
			recalledList = append(recalledList, rumor)
		}
		state.mu.RUnlock()

		recalledResp := recalled{Type: "recalled", Mid: recallReq.Mid, Rumors: recalledList, InReplyTo: recallReq.Mid}
		body, _ = json.Marshal(recalledResp)
		ctx.Write(string(body))
	})

	node.Handle("neighbors", func(ctx *go.Context, msg *go.Message) {
		body := msg.Body.RawBody()

		var topoReq neighborsRequest
		if err := json.Unmarshal(body, &topoReq); err != nil {
			handleOther(ctx, body, state, log.Fatal("unhandled neighbors message"))
		}

		// Store neighbor list - we should talk to all of them
		state.mu.Lock()
		state.neighborList = make([]string, 0, len(topoReq.Neighbors))
		for nid := range topoReq.Neighbors {
			state.neighborList = append(state.neighborList, nid)
		}
		state.mu.Unlock()

		log.Printf("node %s stored neighbors: %v", msg.Src, state.neighborList)

		notedResp := neighborsNoted{Type: "neighbors_noted", InReplyTo: topoReq.Mid}
		respBody, _ := json.Marshal(notedResp)
		ctx.Write(string(respBody))
	})

	node.Run()
}

func handleOther(ctx *go.Context, body []byte, state *nodeState, fatal func(...interface{})) {
	var msg struct {
		Type      string `json:"type"`
		InReplyTo int    `json:"in_reply_to,omitempty"`
		Mid       int    `json:"msg_id,omitempty"`
	}

	if err := json.Unmarshal(body, &msg); err != nil {
		fatal("failed to unmarshal message")
		return
	}

	switch msg.Type {
	case "neighbors_noted":
		type neighborsNotedResp struct {
			Type         string `json:"type"`
			InReplyTo    int    `json:"in_reply_to"`
			NeighborsNoted bool  `json:"neighbors_noted,omitempty"`
		}
		resp := neighborsNotedResp{Type: "neighbors_noted", InReplyTo: msg.InReplyTo}
		body, _ := json.Marshal(resp)
		ctx.Write(string(body))
	case "tell", "broadcast":
		type tell struct {
			Mid    int  `json:"msg_id"`
			Rumor  int  `json:"rumor"`
			Type   string `json:"type"`
		}
		var t tell
		if json.Unmarshal(body, &t) != nil || t.Type != "tell" {
			fatal("unexpected tell structure")
			return
		}

		state.mu.Lock()
		state.knownRumors[t.Rumor] = true
		state.mu.Unlock()

		type told struct {
			Type           string `json:"type"`
			InReplyTo      int    `json:"in_reply_to"`
			NeighborsNoted bool   `json:"neighbors_noted,omitempty"`
		}
		resp := told{Type: "told", InReplyTo: t.Mid}
		body, _ = json.Marshal(resp)
		ctx.Write(string(body))

		for _, neighborID := range state.neighborList {
			if msg.Src != neighborID {
				propMsg := tell{Type: "tell", Rumor: t.Rumor, Mid: t.Mid + 1}
				body, _ = json.Marshal(propMsg)
				ctx.Send(neighborID, string(body))
			}
		}

	case "recall":
		state.mu.RLock()
		recalledList := make([]int, 0)
		for rumor := range state.knownRumors {
			recalledList = append(recalledList, rumor)
		}
		state.mu.RUnlock()

		type recalledResp struct {
			Type       string   `json:"type"`
			Mid        int      `json:"msg_id"`
			Rumors     []int    `json:"rumors"`
			Messages   []int    `json:"messages,omitempty"`
			InReplyTo  int      `json:"in_reply_to"`
		}
		resp := recalledResp{Type: "recalled", Mid: msg.Mid, Rumors: recalledList, InReplyTo: msg.InReplyTo}
		body, _ = json.Marshal(resp)
		ctx.Write(string(body))

	case "told":
		type toldResp struct {
			Type           string `json:"type"`
			InReplyTo      int    `json:"in_reply_to"`
			NeighborsNoted bool   `json:"neighbors_noted,omitempty"`
		}
		resp := toldResp{Type: "told", InReplyTo: msg.InReplyTo}
		body, _ = json.Marshal(resp)
		ctx.Write(string(body))

	case "recalled":
		// Already handled in read handler

	case "neighbors_noted":
		type noted struct {
			Type         string `json:"type"`
			InReplyTo    int    `json:"in_reply_to"`
			NeighborsNoted bool  `json:"neighbors_noted,omitempty"`
		}
		resp := noted{Type: "topology_ok", InReplyTo: msg.InReplyTo}
		body, _ = json.Marshal(resp)
		ctx.Write(string(body))

	case "broadcast_ok":
		type resp struct {
			Type           string `json:"type"`
			InReplyTo      int    `json:"in_reply_to"`
			NeighborsNoted bool   `json:"neighbors_noted,omitempty"`
		}
		resp := resp{Type: "told", InReplyTo: msg.InReplyTo}
		body, _ = json.Marshal(resp)
		ctx.Write(string(body))

	default:
		type resp struct {
			Type           string `json:"type"`
			InReplyTo      int    `json:"in_reply_to"`
			NeighborsNoted bool   `json:"neighbors_noted,omitempty"`
		}
		resp := resp{Type: msg.Type, InReplyTo: msg.InReplyTo}
		body, _ = json.Marshal(resp)
		ctx.Write(string(body))
	}
}
